from collections import deque


def splitTerritory(grid):
    rows, cols = len(grid), len(grid[0])
    INF = float("inf")

    def bfs(kind):
        dist = [[INF] * cols for _ in range(rows)]
        q = deque()
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == kind:
                    dist[r][c] = 0
                    q.append((r, c))
        while q:
            y, x = q.popleft()
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ny, nx = y + dy, x + dx
                if 0 <= ny < rows and 0 <= nx < cols and grid[ny][nx] != 1 and dist[ny][nx] == INF:
                    dist[ny][nx] = dist[y][x] + 1
                    q.append((ny, nx))
        return dist

    da, db = bfs(2), bfs(3)
    a = b = tie = none = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                continue
            if da[r][c] == INF and db[r][c] == INF:
                none += 1
            elif da[r][c] < db[r][c]:
                a += 1
            elif db[r][c] < da[r][c]:
                b += 1
            else:
                tie += 1
    return [a, b, tie, none]
